// Shape the failed-execution payload n8n hands the Error Trigger into an automation_errors row.
const j = $input.first().json || {};
const ex = j.execution || {};
const wf = j.workflow || {};
// correlation_id is best-effort: present only if the failed run exposed it.
const corr = (j.correlation_id) || (ex.correlation_id) || null;
return [{ json: {
  workflow: wf.name || null,
  execution_id: ex.id ? String(ex.id) : null,
  last_node: ex.lastNodeExecuted || null,
  correlation_id: corr,
  message: (ex.error && ex.error.message) || 'unknown error',
  detail: { error: ex.error || null, mode: ex.mode || null, url: ex.url || null }
}}];
